function csv(rows){const keys=[...new Set(rows.flatMap(Object.keys))],quote=v=>'"'+String(v??"").replaceAll('"','""')+'"';return "\ufeff"+keys.join(";")+"\n"+rows.map(r=>keys.map(k=>quote(r[k])).join(";")).join("\n");}
function Field({label,value,set,min,max,step=1,disabled,note}){return <label className="field r27-setting-field"><span className="field-label"><span>{label}</span><ExperimentParameterTooltip text={note}/></span><input aria-label={label} type="number" min={min} max={max} step={step} value={Number.isFinite(value)?value:""} disabled={disabled} onChange={e=>set(e.target.value===""?NaN:Number(e.target.value))}/></label>;}
function Choice({label,value,set,options,disabled}){return <label className="field r27-setting-field"><span className="field-label">{label}</span><select aria-label={label} value={value} disabled={disabled} onChange={e=>set(e.target.value)}>{options.map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label>;}
function TextField({label,value,set,disabled}){return <label className="field r27-setting-field"><span className="field-label">{label}</span><input type="text" aria-label={label} value={value} disabled={disabled} onChange={e=>set(e.target.value)}/></label>;}
function Table({rows,columns,limit=500}){if(!rows?.length)return <p className="r27-note">Нет результатов.</p>;const keys=columns||[...new Set(rows.flatMap(Object.keys))];return <><div className="r27-table-scroll"><table className="r27-table"><thead><tr>{keys.map(k=><th key={k}>{name(k)}</th>)}</tr></thead><tbody>{rows.slice(0,limit).map((r,i)=><tr key={i}>{keys.map(k=><td key={k}>{fmt(r[k],k)}</td>)}</tr>)}</tbody></table></div>{rows.length>limit?<p className="r27-note">Первые {limit} из {rows.length} записей. Полный набор в экспорте JSON/CSV.</p>:null}</>;}
function Plot({data,x,fields,bar=false,ylabel=""}){if(!data?.length)return null;const Chart=bar?BarChart:LineChart,Series=bar?Bar:Line;return <ResponsiveContainer width="100%" height={285}><Chart data={data}><CartesianGrid stroke="#e0e8f0" strokeDasharray="3 3"/><XAxis dataKey={x} tick={{fontSize:11}} tickFormatter={v=>fmt(v)}/><YAxis tick={{fontSize:11}} tickFormatter={v=>fmt(v)} label={ylabel?{value:ylabel,angle:-90,position:"insideLeft"}:undefined}/><Tooltip formatter={(v,n)=>[fmt(v),n]}/><Legend/>{fields.map(([k,n],i)=><Series key={k} dataKey={k} name={n||name(k)} stroke={COLORS[i%COLORS.length]} fill={COLORS[i%COLORS.length]} strokeWidth={2} connectNulls={false} isAnimationActive={false}/>)}</Chart></ResponsiveContainer>;}
function Heatmap({rows,metric,c}){const xs=[...new Set(rows.map(r=>r.x))].sort((a,b)=>a-b),ys=[...new Set(rows.map(r=>r.y))].sort((a,b)=>a-b),vals=rows.map(r=>r[metric]).filter(Number.isFinite),lo=Math.min(...vals),hi=Math.max(...vals);return <div className="r27-table-scroll"><table className="r27-table"><thead><tr><th>{FACTORS[c.factor]?.label} / {FACTORS[c.factor2]?.label}</th>{ys.map(y=><th key={y}>{fmt(y)}</th>)}</tr></thead><tbody>{xs.map(x=><tr key={x}><th>{fmt(x)}</th>{ys.map(y=>{const v=rows.find(r=>r.x===x&&r.y===y)?.[metric];return <td key={y} style={{background:Number.isFinite(v)?"rgba(24,104,173,"+(.06+.44*(hi===lo?.5:(v-lo)/(hi-lo)))+")":undefined}}>{fmt(v,metric)}</td>;})}</tr>)}</tbody></table></div>;}
function GroupingGraph({data}){const N=data.graph.N,by=new Map();data.groups.forEach((g,i)=>g.forEach(a=>by.set(a,i)));const nodes=Array.from({length:N},(_,i)=>({x:180+140*Math.cos(2*Math.PI*i/N),y:165+140*Math.sin(2*Math.PI*i/N)}));return <svg className="r27-playback-svg" viewBox="0 0 360 330" style={{width:"100%",maxHeight:420}} role="img" aria-label="Граф условных информационных зависимостей">{data.graph.edges.filter(e=>e.cmi>=data.threshold).map(e=><line key={e.i+":"+e.j} x1={nodes[e.i].x} y1={nodes[e.i].y} x2={nodes[e.j].x} y2={nodes[e.j].y} stroke="#7894aa" strokeOpacity={.25+.65*e.cmi} strokeWidth={.5+2*e.cmi}/>)}{nodes.map((p,i)=><g key={i}><circle cx={p.x} cy={p.y} r={N>50?4:7} fill={COLORS[(by.get(i)??0)%COLORS.length]}><title>{"A"+(i+1)+" · группа "+((by.get(i)??0)+1)}</title></circle>{N<=35?<text x={p.x} y={p.y-9} textAnchor="middle" fontSize="7">{"A"+(i+1)}</text>:null}</g>)}</svg>;}
function InteractionMap({rows,metric}){const xs=[...new Set(rows.map(r=>r.x))].sort((a,b)=>a-b),ys=[...new Set(rows.map(r=>r.y))].sort((a,b)=>b-a),scale=Math.max(1e-12,...rows.map(r=>Math.abs(r[metric]??0)));return <div className="r27-table-scroll"><h4>{name(metric)}</h4><table className="r27-table"><thead><tr><th>δ / ρ</th>{xs.map(x=><th key={x}>{fmt(x)}</th>)}</tr></thead><tbody>{ys.map(y=><tr key={y}><th>{fmt(y)}</th>{xs.map(x=>{const v=rows.find(r=>r.x===x&&r.y===y)?.[metric];return <td key={x} style={{backgroundColor:Number.isFinite(v)&&Math.abs(v)>1e-10?(v>0?"rgba(199,99,67,":"rgba(62,117,166,")+(0.12+0.65*Math.abs(v)/scale)+")":undefined}}>{fmt(v)}</td>;})}</tr>)}</tbody></table><p className="r27-note">Синий — отрицательный контраст, красный — положительный. Интенсивность нормирована по данной карте.</p></div>;}
