 const update=(k,v)=>{if(busy.current)return;setD(a=>{const b={...a,[k]:v};if(k==="calibrationMode"&&["partial","identified"].includes(v))b.discoverGroups=false;if(k==="factor"||k==="factor2"){const f=FACTORS[v],suffix=k==="factor"?"":"2";b["from"+suffix]=f.min;b["to"+suffix]=f.max;}return b;});clearView();};
 const interactionPreset=kind=>{if(busy.current)return;setD(prev=>({...prev,experiment:"interaction",interactionLaw:"shock",rhoText:".4",rhoScale:1,reps:1,...(kind==="counter"?{groupsText:"9",u0Text:".18",u1Text:".50",prior:.6,b:2.3,f:6.9,d:1.83,c:1.01,rhoFrom:.56,rhoTo:.67,dropFrom:.25,dropTo:.39,interactionLevels:2}:{groupsText:"3",u0Text:".2",u1Text:".8",prior:.5,b:1,f:1,d:0,c:.5,rhoFrom:0,rhoTo:1,dropFrom:0,dropTo:1,interactionLevels:5})}));clearView();};
