    const next=[...saved,data.record];await writeCheckpoint(key,next);if(generation.current!==token)return;saved.push(data.record);setRecords(saved.slice());setProgress({message:"Выполнено расчётных единиц: "+saved.length+" / "+plan.length,completed:saved.length,total:plan.length,percent:100*saved.length/plan.length});w.postMessage({type:"continue",index:saved.length});
